export function ymd(d = new Date()) {
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}
export function parseYmd(s) {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m - 1, d);
}

// Monday of the week containing `d`.
function mondayOf(d) {
  const m = new Date(d);
  m.setDate(m.getDate() - ((m.getDay() + 6) % 7));
  m.setHours(0, 0, 0, 0);
  return m;
}

export function weekNumber(startDate, date = new Date()) {
  if (!startDate) return null;
  const days = Math.round((mondayOf(date) - mondayOf(parseYmd(startDate))) / 86400000);
  return Math.floor(days / 7) + 1;
}

export function phaseOf(week) {
  if (!week || week < 1) return null;
  return PHASES.find((p) => week >= p.from && week <= p.to) || PHASES[PHASES.length - 1];
}

export const isWorkday = (d) => d.getDay() >= 1 && d.getDay() <= 5;

// Consecutive workdays with a check-in, ending today (or the last workday if today isn't done yet).
export function workdayStreak(checkinDates) {
  const set = new Set(checkinDates);
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  if (!set.has(ymd(d))) d.setDate(d.getDate() - 1);
  let n = 0;
  for (let i = 0; i < 400; i++) {
    if (isWorkday(d)) {
      if (!set.has(ymd(d))) break;
      n++;
    }
    d.setDate(d.getDate() - 1);
  }
  return n;
}

// The last `n` workdays before `date` (exclusive), newest first.
export function previousWorkdays(date, n) {
  const out = [];
  const d = new Date(date);
  while (out.length < n) {
    d.setDate(d.getDate() - 1);
    if (isWorkday(d)) out.push(ymd(d));
  }
  return out;
}
